import React, { useState } from 'react';
import '../Styles/style.css';

export default function Navbar() {
    const [isOpen, setIsOpen] = useState(false);

    const closeMenu = () => setIsOpen(false);
    const toggleMenu = () => setIsOpen(!isOpen);

    return (
        <>
            <nav className="navbar">
                {/* Logo - Clic pour fermer */}
                <div className="nav-logo" onClick={closeMenu}>
                    MonLogo
                </div>

                {/* Bouton Hamburger - Visible uniquement sur Mobile */}
                <button
                    className={`hamburger ${isOpen ? 'open' : ''}`}
                    onClick={toggleMenu}
                    aria-label="Menu de navigation"
                >
                    <span className="bar"></span>
                    <span className="bar"></span>
                    <span className="bar"></span>
                </button>

                {/* Liens : En colonne sur PC (à gauche), Déroulant depuis le haut sur Mobile */}
                <div className={`nav-links ${isOpen ? 'active' : ''}`}>
                    <a href="../View/Page1" onClick={closeMenu}>Page 1</a>
                    <a href="../View/Page2" onClick={closeMenu}>Page 2</a>
                </div>
            </nav>

            {/* Voile noir de fermeture en arrière-plan sur mobile */}
            {isOpen && <div className="menu-overlay" onClick={closeMenu}></div>}
        </>
    );
}
